 ('00000000-0000-4000-8000-000000000736','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000734',1,'1.0.0','1.0.0','{"inputMode":"height","buildingLengthMm":10000,"buildingWidthMm":6000,"roofRiseMm":4000,"eaveOverhangMm":0,"frontGableOverhangMm":0,"rearGableOverhangMm":0}','{}','{"source":"DEMO pgTAP"}','verified','[]','00000000-0000-4000-8000-000000000001');
