select '00000000-0000-4000-8000-000000000748','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000735',3,'1.0.0','1.0.0',
  jsonb_set(input_snapshot,'{productInput,effectiveCoveringWidthMm}','900'::jsonb),
  jsonb_set(jsonb_set(jsonb_set(output_snapshot,'{covering,effectiveCoveringWidthMm}','900'::jsonb),'{covering,columnsPerPlane}','12'::jsonb),'{covering,totalSheetCount}','24'::jsonb),data_provenance,validation_status,warnings,created_by
