grant execute on function public.create_gable_metal_tile_takeoff_draft(uuid,uuid,uuid,uuid,uuid,text,uuid,uuid) to postgres;
select is((select draft_created from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO metal tile draft','00000000-0000-4000-8000-000000000741','00000000-0000-4000-8000-000000000001')),true,'saved project metal tile revision creates draft');
select is((select final_quantity from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),20::numeric,'quantity uses sheet count in pieces');
select is((select material_snapshot->>'physicalSheetLengthMm' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'5200','physical length is preserved');
select is((select material_snapshot->>'effectiveCoveringLengthMm' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'5100','effective length is preserved separately');
select is((select material_snapshot->>'moduleCount' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'16','modular count is snapshotted');
select is((select source_calculation_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741'),'00000000-0000-4000-8000-000000000737','exact source calculation revision is preserved');
select is((select material_snapshot->>'sourceCalculationRevisionNumber' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'1','historical calculation revision is selected explicitly');
select is((select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000735'),'00000000-0000-4000-8000-000000000748','source calculation has since advanced to a newer revision');
select is((select source_roof_model_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741'),'00000000-0000-4000-8000-000000000732','exact roof revision is preserved');
select is((select material_snapshot->>'sourceGeometryCalculationRevisionId' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'00000000-0000-4000-8000-000000000736','exact geometry calculation dependency is snapshotted');
select is((select material_snapshot->>'sourceGeometryStaleAtTransfer' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),'true','stale source state is recorded');
select is((select price_snapshot from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')),null::jsonb,'price is not invented');
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741'),'draft','transfer is not auto-approved');
select is((select draft_created from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO metal tile draft','00000000-0000-4000-8000-000000000741','00000000-0000-4000-8000-000000000001')),false,'identical retry reuses existing draft');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO changed name','00000000-0000-4000-8000-000000000741','00000000-0000-4000-8000-000000000001')$$,'22023',null,'changed payload for same operation is rejected');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000740','DEMO wrong module','00000000-0000-4000-8000-000000000742','00000000-0000-4000-8000-000000000001')$$,'22023',null,'catalog modular constraints must match the saved source');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000749','DEMO wrong physical length','00000000-0000-4000-8000-000000000750','00000000-0000-4000-8000-000000000001')$$,'22023',null,'catalog physical length must match the saved source');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000747','00000000-0000-4000-8000-000000000739','DEMO invalid modular source','00000000-0000-4000-8000-000000000748','00000000-0000-4000-8000-000000000001')$$,'22023',null,'invalid modular constraint in source is rejected');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000746','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO wrong project','00000000-0000-4000-8000-000000000743','00000000-0000-4000-8000-000000000001')$$,'P0002',null,'source cannot be transferred into another project');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO wrong org','00000000-0000-4000-8000-000000000744','00000000-0000-4000-8000-000000000001')$$,'42501',null,'cross-organization source access is denied');
select throws_ok($$update public.material_takeoff_items set material_snapshot='{}'::jsonb where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741')$$,'P0001',null,'metal tile source snapshot is immutable');
update public.material_takeoffs set status='approved',approved_by='00000000-0000-4000-8000-000000000001',approved_at=now() where transfer_request_key='00000000-0000-4000-8000-000000000741';
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741'),'approved','existing approval lifecycle can approve the draft');
select is((select draft_created from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO metal tile draft','00000000-0000-4000-8000-000000000741','00000000-0000-4000-8000-000000000001')),false,'retry reuses the approved takeoff without creating another');
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000741'),'approved','retry does not modify approved takeoff');

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is(auth.uid(),'00000000-0000-4000-8000-000000000001'::uuid,'authenticated role resolves the real local Auth subject');
select throws_ok($$select * from public.create_gable_metal_tile_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000730','00000000-0000-4000-8000-000000000735','00000000-0000-4000-8000-000000000737','00000000-0000-4000-8000-000000000739','DEMO direct RPC forged result','00000000-0000-4000-8000-000000000745','00000000-0000-4000-8000-000000000001')$$,'42501',null,'authenticated direct call cannot forge or invoke RPC');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000745'),0,'denied call leaves no takeoff');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select is_empty('select 1 from public.material_takeoffs where transfer_request_key=''00000000-0000-4000-8000-000000000741''','non-member cannot read the transferred takeoff');
select is_empty('select 1 from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key=''00000000-0000-4000-8000-000000000741'')','non-member cannot read transferred item');
select * from finish();
rollback;
